I tried zoxide, but at the end settled for using fzf to quickly find and enter directories:<p><pre><code>  qcd () {
   local d
   dirs=$(fd -t d -t l --ignore-file ~&#x2F;.gitignore . $@)
   d=&quot;$(echo ${dirs} | fzf +m --height=50%)&quot;  &amp;&amp; cd &quot;${d}&quot;
  }

  alias hd=&quot;qcd ${HOME}&quot;</code></pre>
